package io.forgeloop.harness;
import static org.junit.jupiter.api.Assertions.*; import java.util.List; import org.junit.jupiter.api.Test;
class FeatureRunTest { @Test void failedGateIsBoundedAndCannotBecomeReady(){FeatureRun run=new FeatureRun("FEATURE-142");run.plan();run.execute();run.verify();run.record(new VerificationResult("browser",false,"evidence/log.txt","frontend"),1);assertEquals(DeliveryState.REPAIRING,run.state());run.repaired();run.record(new VerificationResult("browser",false,"evidence/log2.txt","frontend"),1);assertEquals(DeliveryState.BLOCKED,run.state());assertThrows(IllegalStateException.class,()->run.ready());} @Test void allGatesPassBeforeReview(){FeatureRun run=new FeatureRun("F");run.plan();run.execute();run.verify();run.review(List.of(new VerificationResult("tests",true,"a","backend")));run.ready();assertEquals(DeliveryState.READY_FOR_REVIEW,run.state());} }
